<script setup>import {timeLabel} from '#shared/utils/format.js';const {data:logs,error}=await useFetch('/api/audit',{default:()=>[]})</script><template><div><LayoutPageHeader title="Audit log" description="Jejak aktivitas penting dalam workspace Anda." eyebrow="ACCOUNTABILITY" /><section class="panel"><p v-if="error" class="error-message">{{ error.data?.statusMessage }}</p><div class="table-wrap"><table><thead><tr><th>Waktu</th><th>User</th><th>Aktivitas</th><th>Data</th><th>Detail</th></tr></thead><tbody><tr v-for="l in logs" :key="l.id"><td>{{ timeLabel(l.createdAt) }}</td><td>{{ l.actorName||'Public booking' }}</td><td>{{ l.action.replaceAll('_',' ') }}</td><td>{{ l.entity }} #{{ l.entityId }}</td><td class="audit-data">{{ JSON.stringify(l.data) }}</td></tr></tbody></table><UiEmptyState v-if="!logs.length" /></div></section></div></template>